/** @type {import('tailwindcss').Config} */
export default {
  content: [
    "./index.html",
    "./src/**/*.{js,ts,jsx,tsx}",
  ],
  theme: {
    extend: {},
  },
  plugins: [],
}

@tailwind base;
@tailwind components;
@tailwind utilities;

body {
  margin: 0;
  padding: 0;
  background-color: #f9fafb;
}

@media (prefers-color-scheme: dark) {
  body {
    background-color: #111827;
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { Send, Settings, Trash2, Moon, Sun, MessageSquare, Brain, Loader2 } from 'lucide-react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

interface Message {
  role: 'user' | 'assistant' | 'system';
  content: string;
  thinking?: string;
}

interface Model {
  name: string;
}

const OLLAMA_BASE_URL = 'http://fedora:11434';

export default function App() {
  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('ollama-messages');
    return saved ? JSON.parse(saved) : [];
  });
  const [input, setInput] = useState('');
  const [models, setModels] = useState<Model[]>([]);
  const [selectedModel, setSelectedModel] = useState<string>(() => {
    return localStorage.getItem('ollama-selected-model') || '';
  });
  const [isThinkingEnabled, setIsThinkingEnabled] = useState(true);
  const [thinkingBudget, setThinkingBudget] = useState(1024);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('ollama-messages', JSON.stringify(messages));
  }, [messages]);

  useEffect(() => {
    localStorage.setItem('ollama-selected-model', selectedModel);
  }, [selectedModel]);

  useEffect(() => {
    fetchModels();
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const fetchModels = async () => {
    try {
      const response = await fetch(`${OLLAMA_BASE_URL}/api/tags`);
      const data = await response.json();
      setModels(data.models || []);
      if (!selectedModel && data.models?.length > 0) {
        setSelectedModel(data.models[0].name);
      }
    } catch (error) {
      console.error('Error fetching models:', error);
    }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSend = async () => {
    if (!input.trim() || !selectedModel || isLoading) return;

    const userMessage: Message = { role: 'user', content: input };
    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    setInput('');
    setIsLoading(true);

    try {
      const response = await fetch(`${OLLAMA_BASE_URL}/api/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: selectedModel,
          messages: newMessages.map(m => ({ role: m.role, content: m.content })),
          stream: true,
          options: {
            num_predict: thinkingBudget, // Using budget as max tokens for now
          }
        }),
      });

      if (!response.body) throw new Error('No body');
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let assistantMessage: Message = { role: 'assistant', content: '', thinking: '' };

      setMessages(prev => [...prev, assistantMessage]);

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        const lines = chunk.split('\n');

        for (const line of lines) {
          if (!line.trim()) continue;
          try {
            const json = JSON.parse(line);
            if (json.message) {
              const content = json.message.content;

              // Handle <think> tags if present in the content
              // This is common for DeepSeek-R1 and similar models
              assistantMessage.content += content;

              // Simple heuristic to extract thinking from content if tags are present
              let currentContent = assistantMessage.content;
              let thinking = '';
              let mainContent = currentContent;

              const thinkMatch = currentContent.match(/<think>([\s\S]*?)<\/think>/);
              if (thinkMatch) {
                thinking = thinkMatch[1];
                mainContent = currentContent.replace(/<think>[\s\S]*?<\/think>/, '').trim();
              } else if (currentContent.includes('<think>')) {
                // In progress thinking
                const parts = currentContent.split('<think>');
                thinking = parts[1] || '';
                mainContent = parts[0];
              }

              setMessages(prev => {
                const updated = [...prev];
                updated[updated.length - 1] = {
                  ...assistantMessage,
                  content: mainContent,
                  thinking: thinking
                };
                return updated;
              });
            }
          } catch (e) {
            console.error('Error parsing JSON chunk:', e);
          }
        }
      }
    } catch (error) {
      console.error('Error sending message:', error);
      setMessages(prev => [...prev, { role: 'system', content: 'Error: Could not connect to Ollama.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  const clearConversation = () => {
    setMessages([]);
    localStorage.removeItem('ollama-messages');
  };

  return (
    <div className="flex flex-col h-screen bg-white dark:bg-gray-950 text-gray-900 dark:text-gray-100">
      {/* Header */}
      <header className="flex items-center justify-between px-6 py-4 border-b border-gray-200 dark:border-gray-800 bg-white/50 dark:bg-gray-950/50 backdrop-blur-md sticky top-0 z-10">
        <div className="flex items-center gap-3">
          <MessageSquare className="w-6 h-6 text-blue-500" />
          <h1 className="text-xl font-bold tracking-tight">Ollama Chat</h1>
        </div>

        <div className="flex items-center gap-4">
          <select 
            value={selectedModel} 
            onChange={(e) => setSelectedModel(e.target.value)}
            className="bg-gray-100 dark:bg-gray-900 border-none rounded-lg px-3 py-1.5 text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none transition-all"
          >
            {models.map(m => (
              <option key={m.name} value={m.name}>{m.name}</option>
            ))}
          </select>

          <button 
            onClick={clearConversation}
            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-900 rounded-full text-gray-500 hover:text-red-500 transition-colors"
            title="Clear Chat"
          >
            <Trash2 className="w-5 h-5" />
          </button>
        </div>
      </header>

      {/* Messages */}
      <main className="flex-1 overflow-y-auto px-4 py-8 max-w-4xl mx-auto w-full space-y-6">
        {messages.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full text-center space-y-4 opacity-50">
            <div className="p-4 bg-gray-100 dark:bg-gray-900 rounded-full">
              <Brain className="w-12 h-12" />
            </div>
            <div>
              <p className="text-lg font-medium">No messages yet</p>
              <p className="text-sm">Select a model and start a conversation</p>
            </div>
          </div>
        )}

        {messages.map((msg, i) => (
          <div key={i} className={cn(
            "flex flex-col space-y-2",
            msg.role === 'user' ? "items-end" : "items-start"
          )}>
            {msg.role === 'assistant' && msg.thinking && isThinkingEnabled && (
              <div className="max-w-[80%] bg-blue-50/50 dark:bg-blue-900/10 border border-blue-100 dark:border-blue-800/50 rounded-2xl px-4 py-3 text-sm italic text-gray-500 dark:text-gray-400">
                <div className="flex items-center gap-2 mb-1 text-blue-500/70 font-semibold not-italic text-xs uppercase tracking-wider">
                  <Brain className="w-3 h-3" />
                  Thinking
                </div>
                {msg.thinking}
              </div>
            )}

            <div className={cn(
              "max-w-[85%] px-5 py-3 rounded-2xl text-sm leading-relaxed shadow-sm",
              msg.role === 'user' 
                ? "bg-blue-600 text-white rounded-br-none" 
                : "bg-white dark:bg-gray-900 border border-gray-100 dark:border-gray-800 rounded-bl-none"
            )}>
              {msg.content || (msg.role === 'assistant' && <Loader2 className="w-4 h-4 animate-spin" />)}
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </main>

      {/* Input */}
      <footer className="p-4 border-t border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-950">
        <div className="max-w-4xl mx-auto space-y-4">
          {/* Controls */}
          <div className="flex items-center gap-6 px-2">
            <div className="flex items-center gap-3">
              <label className="flex items-center cursor-pointer gap-2 select-none">
                <input 
                  type="checkbox" 
                  checked={isThinkingEnabled} 
                  onChange={(e) => setIsThinkingEnabled(e.target.checked)}
                  className="w-4 h-4 rounded border-gray-300 dark:border-gray-700 text-blue-600 focus:ring-blue-500"
                />
                <span className="text-xs font-semibold uppercase tracking-wider text-gray-500">Show Thinking</span>
              </label>
            </div>

            <div className="flex items-center gap-3 flex-1 max-w-xs">
              <span className="text-xs font-semibold uppercase tracking-wider text-gray-500 whitespace-nowrap">Budget: {thinkingBudget}</span>
              <input 
                type="range" 
                min="128" 
                max="8192" 
                step="128"
                value={thinkingBudget} 
                onChange={(e) => setThinkingBudget(Number(e.target.value))}
                className="w-full h-1.5 bg-gray-200 dark:bg-gray-800 rounded-lg appearance-none cursor-pointer accent-blue-600"
              />
            </div>
          </div>

          <div className="relative">
            <textarea
              rows={1}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSend();
                }
              }}
              placeholder="Ask me anything..."
              className="w-full bg-gray-100 dark:bg-gray-900 border-none rounded-2xl px-5 py-4 pr-14 text-sm focus:ring-2 focus:ring-blue-500 outline-none resize-none min-h-[56px] transition-all shadow-inner"
            />
            <button
              onClick={handleSend}
              disabled={isLoading || !input.trim()}
              className="absolute right-3 top-1/2 -translate-y-1/2 p-2 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-300 dark:disabled:bg-gray-800 text-white rounded-xl transition-all shadow-md active:scale-95"
            >
              <Send className="w-5 h-5" />
            </button>
          </div>
          <p className="text-[10px] text-center text-gray-400 font-medium">
            Powered by Ollama • Shift+Enter for new line
          </p>
        </div>
      </footer>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { Send, Settings, Trash2, MessageSquare, Brain, Loader2, Plus, History, ChevronLeft, ChevronRight, MoreVertical } from 'lucide-react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

interface Message {
  role: 'user' | 'assistant' | 'system';
  content: string;
  thinking?: string;
}

interface Conversation {
  id: string;
  title: string;
  messages: Message[];
  createdAt: number;
}

interface Model {
  name: string;
}

const OLLAMA_BASE_URL = 'http://fedora:11434';

export default function App() {
  const [conversations, setConversations] = useState<Conversation[]>(() => {
    const saved = localStorage.getItem('ollama-conversations');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        return [];
      }
    }
    return [];
  });

  const [currentId, setCurrentId] = useState<string>(() => {
    return localStorage.getItem('ollama-current-id') || '';
  });

  const [input, setInput] = useState('');
  const [models, setModels] = useState<Model[]>([]);
  const [selectedModel, setSelectedModel] = useState<string>(() => {
    return localStorage.getItem('ollama-selected-model') || '';
  });
  const [isThinkingEnabled, setIsThinkingEnabled] = useState(true);
  const [thinkingBudget, setThinkingBudget] = useState(1024);
  const [isLoading, setIsLoading] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const currentConversation = conversations.find(c => c.id === currentId) || null;
  const messages = currentConversation?.messages || [];

  useEffect(() => {
    localStorage.setItem('ollama-conversations', JSON.stringify(conversations));
  }, [conversations]);

  useEffect(() => {
    localStorage.setItem('ollama-current-id', currentId);
  }, [currentId]);

  useEffect(() => {
    localStorage.setItem('ollama-selected-model', selectedModel);
  }, [selectedModel]);

  useEffect(() => {
    fetchModels();
    if (conversations.length === 0) {
      createNewConversation();
    }
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const fetchModels = async () => {
    try {
      const response = await fetch(`${OLLAMA_BASE_URL}/api/tags`);
      const data = await response.json();
      setModels(data.models || []);
      if (!selectedModel && data.models?.length > 0) {
        setSelectedModel(data.models[0].name);
      }
    } catch (error) {
      console.error('Error fetching models:', error);
    }
  };

  const createNewConversation = () => {
    const newId = Date.now().toString();
    const newConversation: Conversation = {
      id: newId,
      title: 'New Chat',
      messages: [],
      createdAt: Date.now()
    };
    setConversations(prev => [newConversation, ...prev]);
    setCurrentId(newId);
  };

  const deleteConversation = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setConversations(prev => {
      const filtered = prev.filter(c => c.id !== id);
      if (currentId === id) {
        if (filtered.length > 0) {
          setCurrentId(filtered[0].id);
        } else {
          setCurrentId('');
        }
      }
      return filtered;
    });
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const updateConversationMessages = (id: string, newMessages: Message[]) => {
    setConversations(prev => prev.map(c => {
      if (c.id === id) {
        // Update title based on first message if it's still "New Chat"
        let title = c.title;
        if (title === 'New Chat' && newMessages.length > 0) {
          title = newMessages[0].content.slice(0, 30) + (newMessages[0].content.length > 30 ? '...' : '');
        }
        return { ...c, messages: newMessages, title };
      }
      return c;
    }));
  };

  const handleSend = async () => {
    if (!input.trim() || !selectedModel || isLoading || !currentId) return;

    const userMessage: Message = { role: 'user', content: input };
    const newMessages = [...messages, userMessage];
    updateConversationMessages(currentId, newMessages);
    setInput('');
    setIsLoading(true);

    try {
      const response = await fetch(`${OLLAMA_BASE_URL}/api/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: selectedModel,
          messages: newMessages.map(m => ({ role: m.role, content: m.content })),
          stream: true,
          options: {
            num_predict: thinkingBudget,
          }
        }),
      });

      if (!response.body) throw new Error('No body');
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let assistantContent = '';
      let assistantThinking = '';

      // Initialize assistant message
      const updatedMessagesWithAssistant = [...newMessages, { role: 'assistant', content: '', thinking: '' } as Message];
      updateConversationMessages(currentId, updatedMessagesWithAssistant);

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        const lines = chunk.split('\n');

        for (const line of lines) {
          if (!line.trim()) continue;
          try {
            const json = JSON.parse(line);
            if (json.message) {
              const contentChunk = json.message.content;
              assistantContent += contentChunk;

              let displayContent = assistantContent;
              let thinking = '';

              const thinkMatch = assistantContent.match(/<think>([\s\S]*?)<\/think>/);
              if (thinkMatch) {
                thinking = thinkMatch[1];
                displayContent = assistantContent.replace(/<think>[\s\S]*?<\/think>/, '').trim();
              } else if (assistantContent.includes('<think>')) {
                const parts = assistantContent.split('<think>');
                thinking = parts[1] || '';
                displayContent = parts[0];
              }

              // Update the last message
              setConversations(prev => prev.map(c => {
                if (c.id === currentId) {
                  const msgs = [...c.messages];
                  msgs[msgs.length - 1] = {
                    role: 'assistant',
                    content: displayContent,
                    thinking: thinking
                  };
                  return { ...c, messages: msgs };
                }
                return c;
              }));
            }
          } catch (e) {
            // Ignore parse errors for partial chunks
          }
        }
      }
    } catch (error) {
      console.error('Error sending message:', error);
      updateConversationMessages(currentId, [...newMessages, { role: 'system', content: 'Error: Could not connect to Ollama.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-white dark:bg-gray-950 text-gray-900 dark:text-gray-100 overflow-hidden">
      {/* Sidebar */}
      <aside className={cn(
        "bg-gray-50 dark:bg-gray-900/50 border-r border-gray-200 dark:border-gray-800 transition-all duration-300 flex flex-col",
        isSidebarOpen ? "w-72" : "w-0 overflow-hidden border-none"
      )}>
        <div className="p-4 flex flex-col h-full">
          <button 
            onClick={createNewConversation}
            className="flex items-center gap-2 px-4 py-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-sm font-semibold hover:bg-gray-100 dark:hover:bg-gray-750 transition-all shadow-sm mb-6"
          >
            <Plus className="w-4 h-4" />
            New Chat
          </button>

          <div className="flex-1 overflow-y-auto space-y-1">
            <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest px-2 mb-2">History</div>
            {conversations.map(conv => (
              <div 
                key={conv.id}
                onClick={() => setCurrentId(conv.id)}
                className={cn(
                  "group flex items-center justify-between px-3 py-2.5 rounded-lg cursor-pointer transition-all",
                  currentId === conv.id 
                    ? "bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 shadow-sm" 
                    : "hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-600 dark:text-gray-400"
                )}
              >
                <div className="flex items-center gap-3 min-w-0">
                  <MessageSquare className="w-4 h-4 shrink-0 opacity-70" />
                  <span className="text-sm font-medium truncate">{conv.title}</span>
                </div>
                <button 
                  onClick={(e) => deleteConversation(conv.id, e)}
                  className="opacity-0 group-hover:opacity-100 p-1 hover:bg-red-50 dark:hover:bg-red-900/20 hover:text-red-500 rounded transition-all"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            ))}
          </div>

          <div className="mt-auto pt-4 border-t border-gray-200 dark:border-gray-800">
             <div className="flex items-center gap-3 px-2 py-2">
                <div className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center text-white font-bold text-xs">U</div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold truncate">Local User</p>
                  <p className="text-[10px] text-gray-500 truncate">{OLLAMA_BASE_URL}</p>
                </div>
             </div>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col relative min-w-0">
        {/* Sidebar Toggle */}
        <button 
          onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          className={cn(
            "absolute left-2 top-1/2 -translate-y-1/2 z-20 p-1.5 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-full shadow-md hover:bg-gray-50 dark:hover:bg-gray-800 transition-all",
            !isSidebarOpen && "left-4"
          )}
        >
          {isSidebarOpen ? <ChevronLeft className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
        </button>

        {/* Header */}
        <header className="flex items-center justify-between px-6 py-4 border-b border-gray-200 dark:border-gray-800 bg-white/50 dark:bg-gray-950/50 backdrop-blur-md sticky top-0 z-10">
          <div className="flex items-center gap-4">
            <h1 className="text-xl font-bold tracking-tight">Chat</h1>
            <span className="text-gray-300 dark:text-gray-700">/</span>
            <select 
              value={selectedModel} 
              onChange={(e) => setSelectedModel(e.target.value)}
              className="bg-transparent border-none text-sm font-bold text-blue-600 dark:text-blue-400 focus:ring-0 cursor-pointer hover:underline"
            >
              {models.map(m => (
                <option key={m.name} value={m.name} className="bg-white dark:bg-gray-900 text-gray-900 dark:text-gray-100">{m.name}</option>
              ))}
            </select>
          </div>

          <div className="flex items-center gap-4">
            <div className="text-[10px] text-gray-400 font-mono hidden sm:block">
              {OLLAMA_BASE_URL}
            </div>
            <button 
              className="p-2 hover:bg-gray-100 dark:hover:bg-gray-900 rounded-full text-gray-500 transition-colors"
              title="Settings"
            >
              <Settings className="w-5 h-5" />
            </button>
          </div>
        </header>

        {/* Messages */}
        <main className="flex-1 overflow-y-auto px-4 py-8">
          <div className="max-w-3xl mx-auto space-y-6">
            {messages.length === 0 && (
              <div className="flex flex-col items-center justify-center py-20 text-center space-y-4 opacity-50">
                <div className="p-4 bg-gray-100 dark:bg-gray-900 rounded-full">
                  <Brain className="w-12 h-12" />
                </div>
                <div>
                  <p className="text-lg font-medium">Hello! I'm your local AI.</p>
                  <p className="text-sm">Ask me anything using <b>{selectedModel || 'your selected model'}</b>.</p>
                </div>
              </div>
            )}

            {messages.map((msg, i) => (
              <div key={i} className={cn(
                "flex flex-col space-y-3",
                msg.role === 'user' ? "items-end" : "items-start"
              )}>
                {msg.role === 'assistant' && msg.thinking && isThinkingEnabled && (
                  <div className="max-w-[85%] bg-blue-50/30 dark:bg-blue-900/10 border border-blue-100/50 dark:border-blue-800/30 rounded-2xl px-5 py-4 text-sm text-gray-500 dark:text-gray-400">
                    <div className="flex items-center gap-2 mb-2 text-blue-500/70 font-bold text-[10px] uppercase tracking-widest">
                      <Brain className="w-3.5 h-3.5" />
                      Thought Process
                    </div>
                    <div className="whitespace-pre-wrap italic leading-relaxed">
                      {msg.thinking}
                    </div>
                  </div>
                )}

                <div className={cn(
                  "max-w-[85%] px-5 py-4 rounded-2xl text-sm leading-relaxed",
                  msg.role === 'user' 
                    ? "bg-blue-600 text-white rounded-br-none shadow-blue-500/20 shadow-lg" 
                    : "bg-white dark:bg-gray-900 border border-gray-100 dark:border-gray-800 rounded-bl-none shadow-sm"
                )}>
                  {msg.role === 'assistant' && !msg.content && !msg.thinking ? (
                    <Loader2 className="w-5 h-5 animate-spin text-blue-500" />
                  ) : (
                    <div className="whitespace-pre-wrap">
                      {msg.content}
                    </div>
                  )}
                </div>
              </div>
            ))}
            <div ref={messagesEndRef} />
          </div>
        </main>

        {/* Input */}
        <footer className="p-6 border-t border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-950">
          <div className="max-w-3xl mx-auto space-y-4">
            {/* Controls */}
            <div className="flex flex-wrap items-center gap-x-8 gap-y-4 px-2">
              <div className="flex items-center gap-3">
                <label className="flex items-center cursor-pointer gap-3 group">
                  <div className="relative">
                    <input 
                      type="checkbox" 
                      checked={isThinkingEnabled} 
                      onChange={(e) => setIsThinkingEnabled(e.target.checked)}
                      className="sr-only peer"
                    />
                    <div className="w-10 h-5 bg-gray-200 dark:bg-gray-800 rounded-full peer peer-checked:bg-blue-600 transition-all after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:after:translate-x-5"></div>
                  </div>
                  <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500 group-hover:text-gray-700 dark:group-hover:text-gray-300 transition-colors">Thinking</span>
                </label>
              </div>

              <div className="flex items-center gap-4 flex-1">
                <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500 whitespace-nowrap">Budget: <span className="text-blue-600 dark:text-blue-400 font-mono">{thinkingBudget}</span></span>
                <input 
                  type="range" 
                  min="128" 
                  max="32768" 
                  step="128"
                  value={thinkingBudget} 
                  onChange={(e) => setThinkingBudget(Number(e.target.value))}
                  className="flex-1 h-1 bg-gray-200 dark:bg-gray-800 rounded-lg appearance-none cursor-pointer accent-blue-600"
                />
              </div>
            </div>

            <div className="relative group">
              <textarea
                rows={1}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    handleSend();
                  }
                }}
                placeholder="Type your message..."
                className="w-full bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-2xl px-5 py-4 pr-16 text-sm focus:ring-2 focus:ring-blue-500/50 focus:bg-white dark:focus:bg-gray-850 outline-none resize-none min-h-[56px] transition-all shadow-sm"
              />
              <button
                onClick={handleSend}
                disabled={isLoading || !input.trim()}
                className="absolute right-3 top-[10px] p-2.5 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 dark:disabled:bg-gray-800 disabled:text-gray-400 text-white rounded-xl transition-all shadow-md active:scale-95 z-10"
              >
                <Send className="w-4 h-4" />
              </button>
            </div>
            <div className="flex justify-center">
               <p className="text-[9px] text-gray-400 font-bold uppercase tracking-[0.2em]">
                 Local AI Interface • {selectedModel}
               </p>
            </div>
          </div>
        </footer>
      </div>
    </div>
  );
}
